"use client"

import * as React from "react"

import {
  type PrimitiveError,
  type PrimitiveStatus,
} from "@/lib/retab"
import { cn } from "@/lib/utils"
import { type ViewerPhase, useViewerState } from "@/hooks/use-retab"

export type { ViewerPhase }

/**
 * Convenience wrapper around {@link useViewerState} that returns the phase
 * directly. The state machine itself lives in the headless hooks layer.
 */
export function useViewerPhase(args: {
  status: PrimitiveStatus
  error?: PrimitiveError | null
  hasOutput: boolean
}): ViewerPhase {
  return useViewerState(args).phase
}

const STATUS_LABEL: Record<PrimitiveStatus, string> = {
  pending: "Pending",
  queued: "Queued",
  in_progress: "Running",
  completed: "Completed",
  failed: "Failed",
  cancelled: "Cancelled",
}

export function RetabStatusBadge({
  status,
  className,
}: {
  status: PrimitiveStatus
  className?: string
}) {
  const tone =
    status === "completed"
      ? "text-emerald-700 bg-emerald-50 dark:text-emerald-300 dark:bg-emerald-950"
      : status === "failed" || status === "cancelled"
        ? "text-red-700 bg-red-50 dark:text-red-300 dark:bg-red-950"
        : "text-amber-700 bg-amber-50 dark:text-amber-300 dark:bg-amber-950"

  return (
    <span
      data-slot="retab-status-badge"
      data-status={status}
      className={cn(
        "inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium",
        tone,
        className
      )}
    >
      {STATUS_LABEL[status]}
    </span>
  )
}

export interface RetabViewerShellProps {
  /** Short label, e.g. "Extraction" or the source filename. */
  title?: React.ReactNode
  status: PrimitiveStatus
  error?: PrimitiveError | null
  phase: ViewerPhase
  /** Rendered in the header, right side. */
  actions?: React.ReactNode
  /** Content shown when phase === "empty". */
  emptyMessage?: React.ReactNode
  children: React.ReactNode
  className?: string
  bodyClassName?: string
}

export function RetabViewerShell({
  title,
  status,
  error,
  phase,
  actions,
  emptyMessage = "No output to display.",
  children,
  className,
  bodyClassName,
}: RetabViewerShellProps) {
  return (
    <div
      data-slot="retab-viewer"
      data-phase={phase}
      className={cn(
        "flex h-full min-h-0 flex-col overflow-hidden rounded-xl border bg-card text-card-foreground",
        className
      )}
    >
      <div className="flex h-10 flex-shrink-0 items-center gap-3 border-b px-3">
        <div className="min-w-0 flex-1 truncate text-sm font-medium">
          {title}
        </div>
        <RetabStatusBadge status={status} />
        {actions ? <div className="flex items-center gap-1">{actions}</div> : null}
      </div>
      <div className={cn("min-h-0 flex-1 overflow-auto", bodyClassName)}>
        {phase === "failed" ? (
          <RetabViewerError error={error} />
        ) : phase === "loading" ? (
          <RetabViewerMessage>Waiting for results…</RetabViewerMessage>
        ) : phase === "empty" ? (
          <RetabViewerMessage>{emptyMessage}</RetabViewerMessage>
        ) : (
          children
        )}
      </div>
    </div>
  )
}

function RetabViewerMessage({ children }: { children: React.ReactNode }) {
  return (
    <div className="flex h-full min-h-32 items-center justify-center p-6 text-center text-sm text-muted-foreground">
      {children}
    </div>
  )
}

function RetabViewerError({ error }: { error?: PrimitiveError | null }) {
  return (
    <div className="flex h-full min-h-32 flex-col items-center justify-center gap-1 p-6 text-center">
      <p className="text-sm font-medium text-red-600 dark:text-red-400">
        {error?.message ?? "This operation failed."}
      </p>
      {error?.code ? (
        <p className="font-mono text-xs text-muted-foreground">{error.code}</p>
      ) : null}
    </div>
  )
}
